/**
 * Milestone rows and the per-milestone issue counts behind their progress.
 */
import { and, asc, count, eq, inArray, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, open and closed, in creation order. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(milestones.createdAt), sql`rowid`)
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: {
    name?: string;
    targetDate?: IsoTimestamp | null;
    closedAt?: IsoTimestamp | null;
  },
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined
        ? {}
        : { targetDate: patch.targetDate }),
      ...(patch.closedAt === undefined ? {} : { closedAt: patch.closedAt }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Total / open / closed counts over each milestone's live issues. Milestones
 * without issues are present with zero counts.
 */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const result = new Map<MilestoneId, MilestoneProgress>();
  for (const id of milestoneIds) {
    result.set(id, { total: 0, open: 0, closed: 0 });
  }
  if (milestoneIds.length === 0) return result;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const id = row.milestoneId as MilestoneId;
    const current = result.get(id) ?? { total: 0, open: 0, closed: 0 };
    const isClosed = CLOSED_ISSUE_STATUSES.includes(row.status);
    result.set(id, {
      total: current.total + row.value,
      open: current.open + (isClosed ? 0 : row.value),
      closed: current.closed + (isClosed ? row.value : 0),
    });
  }

  return result;
}
EOF
