/**
 * Project milestones: lifecycle (create, change, close, reopen), the open-milestone cap, per-project name uniqueness and progress.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/** Loads a milestone and its project, both scoped to `orgId`. */
async function loadMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  return { milestone, project };
}

/** Write gate shared by every milestone mutation. */
function assertCanEdit(actor: Actor, project: Project): void {
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
}

async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  except: MilestoneId | null = null,
): Promise<void> {
  const key = milestoneNameKey(name);
  const existing = await milestoneRepo.listMilestonesForProject(
    orgId,
    projectId,
  );
  if (
    existing.some(
      (other) => other.id !== except && milestoneNameKey(other.name) === key,
    )
  ) {
    throw new MilestoneStateError("name_taken", except);
  }
}

async function assertRoomForOpen(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId | null = null,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open", milestoneId);
  }
}

/** Open, dated in the strict past and still carrying open issues. */
function isOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): boolean {
  return (
    milestone.closedAt === null &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < now.getTime() &&
    progress.open > 0
  );
}

async function withProgress(
  orgId: OrgId,
  list: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const now = new Date();
  const progressById = await milestoneRepo.getMilestoneProgress(
    orgId,
    list.map((milestone) => milestone.id),
  );
  return list.map((milestone) => {
    const progress = progressById.get(milestone.id) ?? EMPTY_PROGRESS;
    return { milestone, progress, overdue: isOverdue(milestone, progress, now) };
  });
}

/**
 * Open before closed; then by target date, earliest first, undated last.
 * `list` arrives in creation order and the sort is stable, so ties keep it.
 */
function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  if (a.targetDate === b.targetDate) return 0;
  if (a.targetDate === null) return 1;
  if (b.targetDate === null) return -1;
  return Date.parse(a.targetDate) - Date.parse(b.targetDate);
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCanEdit(actor, project);

  const name = input.name.trim();
  await assertNameFree(input.orgId, project.id, name);
  await assertRoomForOpen(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name,
    targetDate: input.targetDate ?? null,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const { milestone, project } = await loadMilestone(
    input.orgId,
    input.milestoneId,
  );
  assertCanEdit(actor, project);

  const name = input.name === undefined ? undefined : input.name.trim();
  if (name !== undefined) {
    await assertNameFree(input.orgId, project.id, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    ...(name === undefined ? {} : { name }),
    ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
  });
}

/**
 * Closes a milestone, carrying its open live issues to `moveOpenIssuesTo` (or
 * out of any milestone). Every check runs before the first write, so a
 * refused close changes nothing and announces nothing.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const { milestone, project } = await loadMilestone(
    input.orgId,
    input.milestoneId,
  );
  assertCanEdit(actor, project);

  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed", milestone.id);
  }

  const targetId = input.moveOpenIssuesTo ?? null;
  if (targetId !== null) {
    const target = await milestoneRepo.findMilestoneById(input.orgId, targetId);
    if (
      target === null ||
      target.id === milestone.id ||
      target.projectId !== milestone.projectId
    ) {
      throw new NotFoundError("Milestone", targetId);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed", target.id);
    }
  }

  const moved = await issueRepo.moveOpenIssuesOutOfMilestone(
    input.orgId,
    milestone.id,
    targetId,
  );
  const closed = await milestoneRepo.updateMilestone(
    input.orgId,
    milestone.id,
    { closedAt: toNow() },
  );
  const movedIssueIds = moved.map((issue) => issue.id);

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCanEdit(actor, project);

  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open", milestone.id);
  }
  await assertRoomForOpen(orgId, project.id, milestone.id);

  const reopened = await milestoneRepo.updateMilestone(orgId, milestone.id, {
    closedAt: null,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const list = await milestoneRepo.listMilestonesForProject(orgId, project.id);
  const sorted = [...list].sort(compareMilestones);
  return withProgress(orgId, sorted);
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const { milestone, project } = await loadMilestone(orgId, milestoneId);
  assertCan(actor, "project:read", projectResource(project));

  const [result] = await withProgress(orgId, [milestone]);
  return result!;
}

function toNow() {
  return toIsoTimestamp(new Date());
}

