import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { MilestoneStateError } from "@/lib/milestones";
import { toAppError } from "@/lib/errors";
import * as issueService from "@/server/services/issue-service";
import * as ms from "@/server/services/milestone-service";
import * as projectService from "@/server/services/project-service";
import { listNotifications } from "@/server/services/notification-service";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let t: Tenant;
let other: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("ms", "growth");
  other = await createTenant("ms2", "growth");
  registerActivityListeners();
});
afterAll(() => cleanup());

describe("milestones", () => {
  it("works end to end", async () => {
    const closedEvents: unknown[] = [];
    subscribe("milestone.closed", (p) => { closedEvents.push(p); });
    const past = "2020-01-01T00:00:00.000Z" as IsoTimestamp;
    const a = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: " Alpha ", targetDate: past });
    expect(a.name).toBe("Alpha");
    await expect(ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "alpha", targetDate: null })).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(ms.createMilestone(t.actors.viewer, { orgId: t.org.id, projectId: t.project.id, name: "x", targetDate: null })).rejects.toThrow();
    await expect(ms.createMilestone(t.actors.member, { orgId: other.org.id, projectId: t.project.id, name: "x", targetDate: null })).rejects.toBeInstanceOf(TenantScopeError);
    const b = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Beta", targetDate: null });
    const c = await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: "Gamma", targetDate: "2030-01-01T00:00:00.000Z" as IsoTimestamp });

    const i1 = await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin }), milestoneId: a.id });
    expect(i1.milestoneId).toBe(a.id);
    const i2 = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }));
    await issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: i2.id, milestoneId: a.id });
    const i3 = await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id), milestoneId: a.id });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: i3.id, status: "done" });

    let list = await ms.listMilestones(t.actors.viewer, t.org.id, t.project.id);
    expect(list.map((m) => m.milestone.name)).toEqual(["Alpha", "Gamma", "Beta"]);
    expect(list[0]!.progress).toEqual({ total: 3, open: 2, closed: 1 });
    expect(list[0]!.overdue).toBe(true);

    await expect(ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: a.id, moveOpenIssuesTo: a.id })).rejects.toBeInstanceOf(NotFoundError);
    const res = await ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: a.id, moveOpenIssuesTo: b.id });
    expect([...res.movedIssueIds].sort()).toEqual([i1.id, i2.id].sort());
    expect(closedEvents).toHaveLength(1);
    const notes = await listNotifications(t.actors.admin, { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, limit: 25 });
    expect(notes.items.filter((n) => n.kind === "issue_milestone_changed")).toHaveLength(1);
    const notesM = await listNotifications(t.actors.member, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 25 });
    expect(notesM.items.filter((n) => n.kind === "issue_milestone_changed")).toHaveLength(0);

    await expect(ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: a.id, moveOpenIssuesTo: null })).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: i2.id, milestoneId: a.id })).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(ms.closeMilestone(t.actors.member, { orgId: t.org.id, milestoneId: c.id, moveOpenIssuesTo: a.id })).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(ms.reopenMilestone(t.actors.member, t.org.id, b.id)).rejects.toBeInstanceOf(MilestoneStateError);

    list = await ms.listMilestones(t.actors.viewer, t.org.id, t.project.id);
    expect(list.map((m) => m.milestone.name)).toEqual(["Gamma", "Beta", "Alpha"]);
    expect(list[1]!.progress).toEqual({ total: 2, open: 2, closed: 0 });
    expect(list[2]!.progress).toEqual({ total: 1, open: 0, closed: 1 });
    expect(list[2]!.overdue).toBe(false);

    for (let n = 0; n < 8; n += 1) {
      await ms.createMilestone(t.actors.member, { orgId: t.org.id, projectId: t.project.id, name: `M${n}`, targetDate: null });
    }
    const err = await ms.reopenMilestone(t.actors.member, t.org.id, a.id).catch((e) => e);
    expect(err).toBeInstanceOf(MilestoneStateError);
    expect(err.reason).toBe("too_many_open");
    expect(toAppError(err).code).toBe("conflict");

    const otherMs = await ms.createMilestone(other.actors.member, { orgId: other.org.id, projectId: other.project.id, name: "Alpha", targetDate: null });
    await expect(issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: i2.id, milestoneId: otherMs.id })).rejects.toBeInstanceOf(NotFoundError);
    const cleared = await issueService.setIssueMilestone(t.actors.member, { orgId: t.org.id, issueId: i2.id, milestoneId: null });
    expect(cleared.milestoneId).toBeNull();

    const act = await listActivity(t.actors.owner, { orgId: t.org.id, action: ["milestone.closed", "milestone.created"], limit: 50 });
    expect(act.items.length).toBe(11);

    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false });
    await expect(ms.updateMilestone(t.actors.member, { orgId: t.org.id, milestoneId: b.id, name: "B2" })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await ms.listMilestones(t.actors.viewer, t.org.id, t.project.id)).length).toBe(11);
  });
});
EOF
